# One-command local self-build: creates a local signing certificate (once),
# restores NuGet packages and builds a signed, installable Debug|x64 package.
# Output: GameArtManager\AppPackages\..._Debug_Test\*.msixbundle
# Follow up with: tools\sign_and_deploy.ps1 (run elevated) to install it.
param(
    [string]$Configuration = "Debug",
    # only needed when signing an OLD certificate that has a password;
    # certificates generated by this script are passwordless
    [string]$CertPassword = ""
)

$ErrorActionPreference = "Stop"

$repo = Split-Path -Parent $PSScriptRoot
$project = Join-Path $repo "GameArtManager"
$solution = Join-Path $repo "GameArtManager.sln"
$pfx = Join-Path $project "GameArtManager_TemporaryKey.pfx"

# 1. locate MSBuild (needs VS 2022 with the UWP workload)
$vswhere = Join-Path ${env:ProgramFiles(x86)} "Microsoft Visual Studio\Installer\vswhere.exe"
if (-not (Test-Path $vswhere)) {
    throw "vswhere.exe not found - is Visual Studio 2022 installed (with the Universal Windows Platform development workload)?"
}
$msbuild = & $vswhere -latest -products * -requires Microsoft.Component.MSBuild -find "MSBuild\**\Bin\MSBuild.exe" | Select-Object -First 1
if (-not $msbuild) {
    throw "MSBuild not found - install Visual Studio 2022 with the Universal Windows Platform development workload (tools\install_workload.ps1 can add it)."
}

# 2. local signing certificate - generated once, never committed (see .gitignore)
if (-not (Test-Path $pfx)) {
    Write-Host "Creating local test-signing certificate (CN=GameArtManager, no password)..."
    $cert = New-SelfSignedCertificate -Type Custom -Subject "CN=GameArtManager" `
        -KeyUsage DigitalSignature -FriendlyName "GameArtManager local test signing" `
        -CertStoreLocation "Cert:\CurrentUser\My" `
        -TextExtension @("2.5.29.37={text}1.3.6.1.5.5.7.3.3", "2.5.29.19={text}")
    $empty = New-Object System.Security.SecureString
    Export-PfxCertificate -Cert $cert -FilePath $pfx -Password $empty | Out-Null
}

# 3. restore + build the signed package
Write-Host "Restoring packages..."
& $msbuild $solution -t:Restore -p:Configuration=$Configuration -p:Platform=x64 -m -nologo -v:m
if ($LASTEXITCODE -ne 0) { throw "NuGet restore failed" }

Write-Host "Building $Configuration|x64 package..."
$signArgs = @("-p:AppxPackageSigningEnabled=true", "-p:PackageCertificateKeyFile=GameArtManager_TemporaryKey.pfx")
if ($CertPassword -ne "") { $signArgs += "-p:PackageCertificatePassword=$CertPassword" }
& $msbuild $solution -p:Configuration=$Configuration -p:Platform=x64 @signArgs -m -nologo -v:m
if ($LASTEXITCODE -ne 0) { throw "Build failed" }

$bundle = Get-ChildItem (Join-Path $project "AppPackages") -Recurse -Filter *.msixbundle |
    Sort-Object LastWriteTime -Descending | Select-Object -First 1
Write-Host ""
Write-Host "Build OK: $($bundle.FullName)"
Write-Host "Next: run tools\sign_and_deploy.ps1 from an ELEVATED PowerShell to install it."
